# Lingue CLDR con la categoria "many" (numeri grandi): la riempiamo come "other"
MANY = {"it", "es", "fr", "ca"}


def android_escape(text: str) -> str:
    text = escape(text).replace("\\", "\\\\").replace("'", "\\'").replace('"', '\\"')
    return "\\" + text if text[:1] in "@?" else text


def main():
    root = Path(__file__).resolve().parent.parent / "app/src/main/res"
    for i, lang in enumerate(LANGS):
        lines = ['<?xml version="1.0" encoding="utf-8"?>', "<!-- Generato da tools/strings.py: modifica lì, non qui. -->", "<resources>"]
        for key, values in S.items():
            assert len(values) == len(LANGS), key
            extra = ' translatable="false"' if len(set(values)) == 1 and lang == DEFAULT else ""
            if extra or (len(set(values)) == 1 and lang != DEFAULT):
                if lang != DEFAULT:
                    continue
            lines.append(f'    <string name="{key}"{extra}>{android_escape(values[i])}</string>')
        for key, values in P.items():
            assert len(values) == len(LANGS), key
            one, other = values[i]
            lines.append(f'    <plurals name="{key}">')
            lines.append(f'        <item quantity="one">{android_escape(one)}</item>')
            if lang in MANY:
                lines.append(f'        <item quantity="many">{android_escape(other)}</item>')
            lines.append(f'        <item quantity="other">{android_escape(other)}</item>')
            lines.append("    </plurals>")
        lines.append("</resources>")
        folder = root / ("values" if lang == DEFAULT else f"values-{lang}")
        folder.mkdir(parents=True, exist_ok=True)
        (folder / "strings.xml").write_text("\n".join(lines) + "\n", encoding="utf-8")
        print(folder / "strings.xml")


if __name__ == "__main__":
    main()
